def comps(coords, diag=True):
 s=set(coords); res=[]
 while s:
  todo=[s.pop()]; comp=[]
  while todo:
   r,c=todo.pop();comp.append((r,c))
   ns=[(r+dr,c+dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or dr==0 or dc==0)]
   for q in ns:
    if q in s: s.remove(q);todo.append(q)
  res.append(comp)
 return res
sorted([len(x) for x in comps(zeros)],reverse=True), [(len(x),x) for x in comps(zeros)]
